#[test]
fn a_document_reads_as_the_config_reader_reads_it_where_both_read_it() {
    let text = r#"{"response":{"jeu":{"id":"3","noms":[{"region":"ss","text":"G\u00e9"}],"note":{"text":15},"x":null,"y":true}}}"#;
    assert_eq!(parse(text).unwrap(), crate::json::parse(text).unwrap());
}
